//#############################################################################
//# Function: Statically configured arbiter                                   #
//#############################################################################
//# Author:   Andreas Olofsson                                                #
//# License:  MIT (see LICENSE file in OH! repository)                        #
//#############################################################################

module oh_arbiter
  #( parameter N    = 1,
     parameter TYPE = "FIXED" // or ROUNDROBIN, FAIR
     )
   (
    input [N-1:0]  requests, //request vector
    output [N-1:0] grants    //grant (one hot)
    );

   wire [N-1:0]   waitmask;
   genvar 	  j;
   generate
      if(TYPE=="FIXED")
	begin : arbiter_fixed
	   assign waitmask[0]   = 1'b0;
	   for (j=N-1; j>=1; j=j-1)
	     begin : gen_arbiter
		assign waitmask[j] = |requests[j-1:0];
	     end
	end
   endgenerate

   //grant circuit
   assign grants[N-1:0] = requests[N-1:0] & ~waitmask[N-1:0];

endmodule // oh_arbiter

//#############################################################################
//# Function: Random length pulse generator
//#############################################################################
//# Author:   Andreas Olofsson                                                #
//# License:  MIT (see LICENSE file in OH! repository)                        #
//#############################################################################

module oh_pulse
  #(parameter N = 32 //width of counter (max value)
    )
   (
    input 	  clk,
    input 	  nreset,
    input 	  en, //enable pulse generator
    input [N-1:0] mask, //mask output to limit range
    output reg 	  out  //random output pulse
    );

   wire [N-1:0]   random;
   reg [N-1:0] 	  counter;
   wire 	  match;

   oh_random oh_random(//output
		       .out	(random[N-1:0]),
		       // Inputs
		       .clk	(clk),
		       .mask    (mask[N-1:0]),
		       .nreset	(nreset),
		       .en	(match));

   assign match = (random[N-1:0] == counter[N-1:0]);

   always @ (posedge clk or negedge nreset)
     if(~nreset)
       counter[N-1:0] <= 'b0;
     else if(match)
       counter[N-1:0] <= 'b0;
     else
       counter[N-1:0] <= counter[N-1:0] + 1;

   always @ (posedge clk or negedge nreset)
     if(~nreset)
       out <= 'b0;
     else
       out <= out ^ match;

endmodule // oh_pulse

//#############################################################################
//# Purpose: Stretches a pulse by N+1 clock cycles                            #
//#          Adds one cycle latency                                           #
//#############################################################################
//# Author:   Andreas Olofsson                                                #
//# License:  MIT (see LICENSE file in OH! repository)                        #
//#############################################################################

module oh_stretcher #(parameter CYCLES = 5) // "wakeup" cycles
   ( input  clk, // clock
     input  in, // input pulse
     input  nreset, // async active low reset
     output out // stretched output pulse
     );

   reg [CYCLES-1:0] valid;

   always @ (posedge clk or negedge nreset)
     if(!nreset)
       valid[CYCLES-1:0] <='b0;
     else if(in)
       valid[CYCLES-1:0] <={(CYCLES){1'b1}};
     else
       valid[CYCLES-1:0] <={valid[CYCLES-2:0],1'b0};

   assign out = valid[CYCLES-1];

endmodule // oh_stretcher

//#############################################################################
//# Function: A digital debouncer circuit                                     #
//#############################################################################
//# Author:   Andreas Olofsson                                                #
//# License:  MIT (see LICENSE file in OH! repository)                        #
//#############################################################################

module oh_debouncer
  #( parameter BOUNCE    = 100,      // bounce time (s)
     parameter FREQUENCY = 1000000,  // clock frequency (1Mhz)
     parameter SYN       = "TRUE",   // synthesizable (or not)
     parameter TYPE      = "DEFAULT" // scell type/size
     )
   (
    input  clk, // clock to synchronize to
    input  nreset, // syncronous active high reset
    input  noisy_in, // noisy input signal to filter
    output clean_out // clean signal to logic
    );

   parameter integer COUNTER_WIDTH  = $clog2(BOUNCE*FREQUENCY);

   //regs
   reg 	  noisy_reg;
   reg 	  clean_reg;

   // synchronize incoming signal
   oh_dsync #(.SYN(SYN),
	      .TYPE(TYPE))
   dsync (.dout   (noisy_synced),
	  .clk    (clk),
	  .nreset (nreset),
	  .din	  (noisy_in));

   // synchronize reset to clk
   oh_rsync #(.SYN(SYN),
	      .TYPE(TYPE))
   rsync (.nrst_out (nreset_synced),
	  .clk	    (clk),
	  .nrst_in  (nreset));

   // detecting change in state on input
   always @ (posedge clk or negedge nreset)
     if(!nreset)
       noisy_reg <= 1'b0;
     else
       noisy_reg <= noisy_synced;

   assign change_detected = noisy_reg ^ noisy_synced;

   // synchronous counter "filter"
   oh_counter #(.N(COUNTER_WIDTH),
		.SYN(SYN),
		.TYPE(TYPE))
   oh_counter (// Outputs
	       .count	   (),
	       .wraparound (wraparound),
	       // Inputs
	       .clk	   (clk),
	       .in	   (1'b1),
	       .dec        (1'b0),
	       .en	   (1'b1),
	       .autowrap   (1'b0),
	       .load  	   (change_detected | ~nreset_synced),
	       .load_data  ({(COUNTER_WIDTH){1'b0}})
	       );

   // sample noisy signal safely
   always @ (posedge clk or negedge nreset)
     if(!nreset)
       clean_reg <= 'b0;
     else if(wraparound)
       clean_reg <= noisy_reg;

   assign clean_out = clean_reg;

endmodule // oh_debouncer

//#############################################################################
//# Function: Generic counter                                                 #
//#############################################################################
//# Author:   Andreas Olofsson                                                #
//# License:  MIT (see LICENSE file in OH! repository)                        #
//#############################################################################

module oh_counter
  #(parameter N   = 32,       // width of data inputs
    parameter SYN = "TRUE",   // synthesizable
    parameter TYPE = "DEFAULT"// implementation type
    )
   (
    //inputs
    input 	       clk, // clk input
    input 	       in, // input to count
    input 	       en, // enable counter
    input 	       dec,//1=decrement, 0 = increment
    input 	       autowrap, //auto wrap counter
    input 	       load, // load counter
    input [N-1:0]      load_data, // input data to load
    //outputs
    output reg [N-1:0] count, // count value
    output 	       wraparound // wraparound indicator
    );

   wire [N-1:0]	 inb;
   wire [N-1:0]  count_in;

   //Increment decrement option
   assign inb[N-1:0] = dec ? {{(N-1){1'b1}},~in} : {{(N-1){1'b0}},in};
   assign cin        = dec ? 1'b1 : 1'b0;

   // counter
   always @(posedge clk)
     if(load)
       count[N-1:0] <= load_data[N-1:0];
     else if (en & ~(wraparound & ~autowrap))
       count[N-1:0] <= count_in[N-1:0];

   assign wraparound = (dec & en & ~(|count[N-1:0])) |
		       (~dec & en & (&count[N-1:0]));

   // Soft/hard adder
   generate
      if(SYN == "TRUE")  begin
	 assign count_in[N-1:0] =count[N-1:0] + inb[N-1:0];
      end
      else begin
	 asic_add #(.TYPE(TYPE),
		    .N(N))
	 asic_add (// Outputs
		   .sum		(cout_in[N-1:0]),
		   .carry	(),
		   .cout	(),
		   // Inputs
		   .a		(count[N-1:0]),
		   .b		(in_mux[N-1:0]),
		   .k		({(N){1'b0}}),
		   .cin		(cin));
      end
   endgenerate

endmodule // oh_counter

